{
  "segment_function": "argument",
  "claims": [
    {
      "claim": "Modern philosophy began with Descartes' universal doubt, which replaced the Greek wonder (thaumazein) as the central motor and axis of philosophical thought.",
      "claim_type": "author_position",
      "supporting_excerpt": "Modern philosophy began with Descartes’ de omnibus dubitandum est , with doubt, but with doubt not as an inherent control of the human mind to guard against deceptions of thought and illusions of sense, not as skepticism against the morals and prejudices of men and times, not even as a critical method in scientific inquiry and philosophic speculation. Cartesian doubt is much more far-reaching in scope and too fundamental in intent to be determined by such concrete contents. In modern philosophy and thought, doubt occupies much the same central position as that occupied for all the centuries before by the Greek thaumazein , the wonder at everything that is as it is.",
      "support_kind": "direct",
      "qualifications": [
        "not as an inherent control of the human mind",
        "not as skepticism against morals and prejudices",
        "not even as a critical method in scientific inquiry"
      ],
      "confidence": 1
    },
    {
      "claim": "Cartesian doubt arose fundamentally in response to a new reality produced by man-made instruments like the telescope, which showed that neither truth nor reality is given in appearance.",
      "claim_type": "author_position",
      "supporting_excerpt": "Cartesian doubt, in its radical and universal significance, was originally the response to a new reality, a reality no less real for its being restricted for centuries to the small and politically insignificant circle of scholars and learned men. The philosophers understood at once that Galileo’s discoveries implied no mere challenge to the testimony of the senses and that it was no longer reason... but a man-made instrument, the telescope, which actually changed the physical world view",
      "support_kind": "direct",
      "qualifications": [
        "restricted for centuries to the small and politically insignificant circle of scholars and learned men"
      ],
      "confidence": 1
    }
  ],
  "definitions": [
    {
      "term": "Cartesian doubt",
      "definition": "A radical and universal doubt occupying the central position in modern philosophy, originating as a response to the realization that Being and Appearance part company and that truth and reality do not simply reveal themselves to human senses or reason."
    }
  ],
  "distinctions": [
    {
      "item_a": "Greek thaumazein (wonder)",
      "item_b": "Cartesian doubting",
      "distinction": "Thaumazein was the wonder at everything that is as it is, which occupied the central position for all centuries before modern philosophy, whereas modern philosophy since Descartes consists in the articulations and ramifications of doubting."
    }
  ],
  "references_to_other_sections": [],
  "unresolved_context": [],
  "must_not_be_lost": [
    "Descartes' doubt is universal and arises from the loss of self-evidence and the split between Being and Appearance."
  ]
}

